function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function call(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function run(input){const op=String(input.operation||''),id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const base='/api/data-sync/recipes/'+encodeURIComponent(id);const workspace=await call(base);const draft=workspace.draft;if(op==='get')return workspace;if(!draft||!draft.source_sha256)throw new Error('Project data recipe is not initialized');if(op==='plan'||op==='run'){if(input.confirm_python_execution!==true)throw new Error('Executing recipe.py requires explicit Python execution confirmation');return call(base+(op==='plan'?'/plan':'/jobs'),{method:'POST',body:JSON.stringify({confirm_python_execution:true})})}if(op==='save_template'){if(input.confirm_save!==true)throw new Error('Saving a reusable recipe template requires explicit confirmation');if(!input.name)throw new Error('name is required');return call(base+'/templates',{method:'POST',body:JSON.stringify({name:String(input.name),description:String(input.description||''),expected_source_sha256:draft.source_sha256,confirm_save:true})})}if(input.confirm_write!==true)throw new Error('Editing recipe.py requires confirm_write=true');if(op==='replace_source'){if(!input.source)throw new Error('complete recipe.py source is required');await call(base,{method:'PUT',body:JSON.stringify({source:input.source,expected_source_sha256:draft.source_sha256,confirm_write:true})})}else if(op==='apply_template'){if(!input.template_id)throw new Error('template_id is required');await call(base+'/templates/'+encodeURIComponent(String(input.template_id)),{method:'POST',body:JSON.stringify({expected_source_sha256:draft.source_sha256,confirm_write:true})})}else if(op==='update_parameters'){if(!input.start||!input.end)throw new Error('start and end are required');await call(base+'/parameters',{method:'PATCH',body:JSON.stringify({start:String(input.start),end:String(input.end),symbols:input.symbols===undefined?null:input.symbols,expected_source_sha256:draft.source_sha256,confirm_write:true})})}else throw new Error('unsupported data recipe operation');return call(base)}
